<script setup lang="ts">
import type { PostScope } from '~/types/feed'
import { useAuthStore } from '~/stores/auth'

const props = defineProps<{
  scope?: PostScope
  batchYear?: number
}>()

const emit = defineEmits<{
  posted: []
}>()

const { createPost } = useFeed()
const authStore = useAuthStore()
const toast = useToast()

const content = ref('')
const loading = ref(false)
const expanded = ref(false)

async function handlePost() {
  if (!content.value.trim()) return

  loading.value = true
  const result = await createPost(
    content.value.trim(),
    [],
    props.scope || 'general',
    props.batchYear,
  )

  if (result.success) {
    content.value = ''
    expanded.value = false
    emit('posted')
    toast.add({ severity: 'success', summary: 'Post shared!', life: 2000 })
  }
  else {
    toast.add({ severity: 'error', summary: 'Failed to post', detail: result.error, life: 3000 })
  }

  loading.value = false
}
</script>

<template>
  <div class="bg-white border border-slate-200 rounded-xl p-4">
    <div class="flex gap-3">
      <!-- Avatar -->
      <div class="shrink-0">
        <img
          v-if="authStore.profile?.avatar_url"
          :src="authStore.profile.avatar_url"
          class="w-9 h-9 rounded-full object-cover"
          alt="Your avatar"
        >
        <div
          v-else
          class="w-9 h-9 rounded-full bg-primary-100 flex items-center justify-center text-primary-700 font-medium text-sm"
        >
          {{ authStore.displayName.charAt(0).toUpperCase() }}
        </div>
      </div>

      <div class="flex-1">
        <textarea
          v-model="content"
          :rows="expanded ? 4 : 2"
          placeholder="Share something with your alumni network..."
          class="w-full resize-none border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-primary-400 focus:ring-1 focus:ring-primary-200 transition-all"
          @focus="expanded = true"
        />

        <div v-if="expanded" class="flex items-center justify-between mt-2">
          <div class="flex gap-2">
            <span v-if="scope === 'batch' && batchYear" class="text-xs text-primary-600 bg-primary-50 px-2 py-1 rounded-full">
              Batch {{ batchYear }} feed
            </span>
            <span v-else class="text-xs text-slate-500 bg-slate-50 px-2 py-1 rounded-full">
              General feed
            </span>
          </div>
          <div class="flex gap-2">
            <button
              class="px-3 py-1.5 text-sm text-slate-600 hover:bg-slate-50 rounded-lg transition-colors"
              @click="expanded = false; content = ''"
            >
              Cancel
            </button>
            <button
              class="px-4 py-1.5 text-sm font-medium text-white bg-primary-600 hover:bg-primary-700 rounded-lg transition-colors disabled:opacity-50"
              :disabled="!content.trim() || loading"
              @click="handlePost"
            >
              <i v-if="loading" class="pi pi-spin pi-spinner mr-1" />
              Post
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
